#include <iostream>
#include <iomanip>
#include <vector>
using namespace std;

int maxOf(const vector<int> &a)
{
    int i, m = a[0];

    for (i = 1; i < (int)a.size(); i++)
        if (a[i] > m)
            m = a[i];
    return m;
}

int minOf(const vector<int> &a)
{
    int i, m = a[0];

    for (i = 1; i < (int)a.size(); i++)
        if (a[i] < m)
            m = a[i];
    return m;
}

double avgOf(const vector<int> &a)
{
    int i, sum = 0;

    for (i = 0; i < (int)a.size(); i++)
        sum += a[i];
    return (double)sum / (int)a.size();
}

int main()
{
    int n, i;
    vector<int> a;

    cin >> n;
    a.resize(n);
    for (i = 0; i < n; i++)
        cin >> a[i];
    cout << maxOf(a) << " " << minOf(a) << " "
         << fixed << setprecision(2) << avgOf(a) << endl;
    return 0;
}

