using namespace std;

static int abs_int(int x)
{
    return x < 0 ? -x : x;
}

int cmp(const void *pa, const void *pb)
{
    int a = *(const int *)pa;
    int b = *(const int *)pb;
    int aa = abs_int(a);
    int bb = abs_int(b);

    if (aa != bb)
        return aa < bb ? -1 : 1;
    if (a == b)
        return 0;
    return a < b ? -1 : 1;
