指-67.solution:
#include <iostream>
#include <cstddef>
using namespace std;

int cmp_int(const void *pa, const void *pb)
{
    int a = *(const int *)pa;
    int b = *(const int *)pb;

    return (a > b) - (a < b);
}

static void swap_bytes(char *x, char *y, size_t size)
{
    size_t i;

    for (i = 0; i < size; i++) {
        char t = x[i];
        x[i] = y[i];
        y[i] = t;
    }
}

void sort(void *base, size_t n, size_t size, int (*cmp)(const void *, const void *))
{
    char *p = (char *)base;
    size_t i, j, best;

    for (i = 0; i + 1 < n; i++) {
        best = i;
        for (j = i + 1; j < n; j++)
            if (cmp(p + j * size, p + best * size) < 0)
                best = j;
        if (best != i)
            swap_bytes(p + i * size, p + best * size, size);
    }
}

int main()
{
    int a[50], n, i;

    if (!(cin >> n) || n <= 0 || n > 50)
        return 0;
    for (i = 0; i < n; i++)
        cin >> a[i];

    sort(a, (size_t)n, sizeof(int), cmp_int);

    for (i = 0; i < n; i++)
        cout << a[i] << (i < n - 1 ? ' ' : '\n');
    return 0;
}

