#include <cstdio>
using namespace std;

enum State { IDLE, RUNNING, PAUSED, STOPPED };

static const char *state_name[] = {"IDLE", "RUNNING", "PAUSED", "STOPPED"};

State next(State s, char cmd)
{
    switch (s) {
    case IDLE:
        return (cmd == 's') ? RUNNING : IDLE;
    case RUNNING:
        if (cmd == 'p')
            return PAUSED;
        if (cmd == 'x')
            return STOPPED;
        return RUNNING;
    case PAUSED:
        if (cmd == 'r')
            return ①;
        if (cmd == 'x')
            return STOPPED;
        return PAUSED;
    case ②:
        return STOPPED;
    }
    return s;
}

int main()
{
    char cmd;
    State s = IDLE;

    while (scanf(" %c", &cmd) == 1)
        s = ③(s, cmd);

    printf("%s\n", state_name[s]);
    return 0;
}
```

